const params = new URLSearchParams(location.search);
let direction = params.get('direction') === 'editorial' ? 'editorial' : 'practical';
let screen = ['home','day','import'].includes(params.get('screen')) ? params.get('screen') : 'home';
let filter = 'all', imported = false;
const done = new Set();
const activities = [
  ['09:00','Flâner au bord de la rivière Li','Balade · Yangshuo','Un départ tranquille, à pied depuis le centre.'],
  ['12:00','Déjeuner dans West Street','À table · 西街','Une pause libre pour goûter la cuisine locale.'],
  ['15:00','Les chemins de la rivière Yulong','Paysage · 遇龙河','Adresses et temps de trajet à vérifier.'],
];
const art = (city=false) => `<svg viewBox="0 0 700 260" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="700" height="260" fill="${city?'#d8d9cc':'#d4ddd0'}"/><circle cx="550" cy="62" r="37" fill="#d4b778"/>${city?'<path d="M0 130L100 90 190 140 290 70 420 130 540 65 700 130V260H0Z" fill="#b19a79"/><path d="M0 200H700V260H0Z" fill="#668c92"/><g fill="#eee5cb"><path d="M65 110h70v100H65zM170 150h80v70h-80zM320 105h70v120h-70zM460 120h85v100h-85z"/></g>':'<path d="M0 210Q50 190 90 100Q120 10 160 160Q200 210 240 95Q275 -15 320 160Q350 200 380 90Q420 -30 460 150Q500 220 550 110Q580 30 620 155L700 200V260H0Z" fill="#7f9c87"/><path d="M0 260V225Q100 120 200 230Q280 160 350 230Q440 140 500 215Q630 140 700 220V260Z" fill="#355d50"/><path d="M400 260Q270 230 440 205Q530 185 480 175Q630 195 480 220Q350 240 520 260Z" fill="#cbd7c1"/>'}</svg>`;
function go(next) {screen=next; render(); document.querySelector('h1').focus(); window.scrollTo(0,0);}
function details(title,body) {document.querySelector('#detail-content').innerHTML=`<h2>${title}</h2><p>${body}</p>`; document.querySelector('#detail').showModal();}
function home() {return `<div class="heading"><div><p class="eyebrow">LES VOYAGES À VENIR</p><h1 tabindex="-1">Mes voyages</h1><p class="description">Des idées qui prennent le large.</p></div><button class="primary" data-screen="import">＋ Ajouter depuis un fichier</button></div><div class="filters" aria-label="Filtrer les voyages">${[['all','Tous'],['prep','En préparation'],['idea','Idées']].map(([k,v])=>`<button data-filter="${k}" aria-pressed="${filter===k}">${v}</button>`).join('')}<span class="count">${filter==='all'?2:1} carnet${filter==='all'?'s':''}</span></div><div class="trip-grid">${filter!=='idea'?`<article class="trip"><div class="trip-art">${art()}<span class="badge">En préparation</span></div><div class="trip-body"><p class="eyebrow">CHINE · 17 JOURS</p><h2>Au fil de la Chine</h2><p class="meta">8 — 24 mai 2027<br>Shenzhen · Yangshuo · Chengdu</p><div class="trip-foot"><span>7 villes · 17 journées</span><button class="text-button" data-screen="day">Ouvrir le carnet →</button></div></div></article>`:''}${filter!=='prep'?`<article class="trip"><div class="trip-art">${art(true)}<span class="badge">Idée</span></div><div class="trip-body"><p class="eyebrow">PORTUGAL · UNE ÉCHAPPÉE</p><h2>Les collines de Lisbonne</h2><p class="meta">Dates à choisir<br>Alfama · Graça · Belém</p><div class="trip-foot"><span>3 quartiers à découvrir</span><button class="text-button" data-detail="lisbon">Voir l’idée →</button></div></div></article>`:''}</div><div class="section-head"><h2>Un peu de préparation</h2><span class="meta">À ton rythme</span></div><div class="prep-grid"><button class="prep" data-screen="day"><span class="icon">◷</span><span><strong>Reprendre la journée</strong><small>Yangshuo · mercredi 12 mai</small></span></button><button class="prep" data-screen="import"><span class="icon">↥</span><span><strong>Vérifier un import</strong><small>Un aperçu avant d’ajouter</small></span></button><button class="prep" data-detail="backup"><span class="icon">◇</span><span><strong>Mes sauvegardes</strong><small>Garder une copie de ses souvenirs</small></span></button></div>`;}
function day() {return `<div class="breadcrumb"><button data-screen="home">Mes voyages</button> / Au fil de la Chine</div><div class="heading"><div><p class="eyebrow">JOUR 5 · MERCREDI 12 MAI 2027</p><h1 tabindex="-1">Une journée à Yangshuo</h1><p class="description">Entre rivière et chemins de traverse.</p></div><button class="secondary" data-detail="prepare">Préparer la journée</button></div><div class="day-summary"><span>3 activités</span><span>·</span><span id="progress">${done.size} sur 3 vécues</span><span>· À pied et à vélo</span></div><div class="day-layout"><section aria-label="Activités de la journée"><div class="timeline">${activities.map((a,i)=>`<article class="activity"><time>${a[0]}</time><div><span class="badge">${a[2]}</span><h3>${a[1]}</h3><p>${a[3]}</p><button class="text-button" data-activity="${i}">Voir les détails →</button></div><label class="check-target"><input type="checkbox" data-done="${i}" aria-label="Marquer comme vécue : ${a[1]}" ${done.has(i)?'checked':''}></label></article>${i<2?'<div class="connection">↓ Temps de trajet à confirmer</div>':''}`).join('')}</div><p class="safe-note">Horaires fictifs pour comparer les interfaces, sans réservation.</p></section><aside class="day-aside"><section class="side-card"><div class="map-art">${art()}</div><div class="inner"><p class="eyebrow">LE REPÈRE DU JOUR</p><h2>Suivre la rivière</h2><p>Yangshuo · 阳朔</p><p>Illustration, pas une carte de navigation.</p><button class="text-button" data-detail="address">Voir le repère →</button></div></section><section class="side-card"><div class="inner"><h2>À garder en tête</h2><p>Prendre de l’eau. Vérifier la météo et les possibilités de location de vélo sur place.</p><button class="text-button" data-detail="rain">Et s’il pleut ? →</button></div></section></aside></div>`;}
function preview() {return `<div class="heading"><div><p class="eyebrow">AJOUTER UN CARNET</p><h1 tabindex="-1">${imported?'Le carnet est prêt':'Un dernier regard'}</h1><p class="description">${imported?'Simulation terminée. Aucun carnet réel n’a été créé.':'Vérifie ce qui sera ajouté à tes voyages.'}</p></div></div><div class="steps"><span>1 · Fichier choisi</span><span class="current">2 · Aperçu</span><span>3 · Ajouter une copie</span></div><div class="import-layout"><section class="import-card"><div class="file"><span class="file-icon">↥</span><div><strong>chine-mai-2027.json</strong><br><small>Fichier fictif · 142 Ko</small></div></div><h2>Au fil de la Chine</h2><p class="meta">8 — 24 mai 2027 · Shenzhen, Yangshuo, Chengdu</p><div class="stats"><div><b>1</b>carnet</div><div><b>17</b>journées</div><div><b>42</b>activités</div></div><div class="notice"><strong>2 informations à compléter</strong><br>Une adresse et un horaire manquent. Tu pourras les ajouter plus tard.</div><h3>Aperçu · mercredi 12 mai</h3>${activities.map(a=>`<div class="import-row"><time>${a[0]}</time><div>${a[1]}<small>${a[2]}</small></div></div>`).join('')}<details><summary>Voir les informations à compléter</summary><p class="safe-note">Adresse précise de la location de vélo et horaire du train du 14 mai. Aucun horaire n’est déduit automatiquement.</p></details></section><aside class="import-card"><p class="eyebrow">UNE COPIE INDÉPENDANTE</p><h2>Ton carnet reste à toi.</h2><p class="safe-note">L’ajout crée un nouveau carnet privé. Tes voyages existants restent conservés.</p><hr class="mini-rule"><p class="safe-note">Démonstration uniquement : aucun fichier lu, aucune donnée enregistrée ou envoyée.</p><button class="primary full" id="confirm-import">${imported?'Recommencer la simulation':'Simuler l’ajout du carnet'}</button><button class="text-button" data-screen="home">Revenir à mes voyages</button><p id="import-status" role="status" class="safe-note">${imported?'✓ Copie fictive ajoutée. Recharge la page pour réinitialiser.':''}</p></aside></div>`;}
function render() {
 document.body.className=direction;
 history.replaceState(null,'',`?direction=${direction}&screen=${screen}`);
 document.querySelector('#app').innerHTML=`<header class="workshop"><strong>ATELIER DÉTOURS · DONNÉES FICTIVES</strong><div class="switch" aria-label="Direction visuelle"><button data-direction="editorial" aria-pressed="${direction==='editorial'}">A · Carnet éditorial</button><button data-direction="practical" aria-pressed="${direction==='practical'}">B · Compagnon pratique</button></div></header><div class="shell"><aside class="sidebar"><div class="brand">détours<span>.</span></div><p class="small-label">LE MONDE À TON RYTHME</p><nav class="nav" aria-label="Écrans du prototype">${[['home','Mes voyages','◈'],['day','Ma journée','◷'],['import','Aperçu import','↥']].map(([k,v,icon])=>`<button data-screen="${k}" class="${screen===k?'active':''}" ${screen===k?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${v}</button>`).join('')}</nav><p class="sidebar-note">Prendre le temps.<br>Garder l’envie de découvrir.</p></aside><main id="main"><div class="topline"><span>Le carnet de tes échappées</span><span>○ Démonstration locale</span></div>${screen==='home'?home():screen==='day'?day():preview()}<footer><span>Détours · Les beaux détours</span><span>Prototype ${direction==='editorial'?'A':'B'} · aucune donnée réelle</span></footer></main></div>`;
 document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>go(b.dataset.screen));
 document.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>{direction=b.dataset.direction;render();document.querySelector(`[data-direction="${direction}"]`).focus();});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();document.querySelector(`[data-filter="${filter}"]`).focus();});
 document.querySelectorAll('[data-done]').forEach(b=>b.onchange=()=>{const i=Number(b.dataset.done);b.checked?done.add(i):done.delete(i);document.querySelector('#progress').textContent=`${done.size} sur 3 vécues`;});
 document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{const a=activities[Number(b.dataset.activity)];details(a[1],`${a[0]} · ${a[2]}. ${a[3]} Ce contenu est fictif ; les détails opérationnels restent à confirmer.`);});
 const notes={lisbon:['Les collines de Lisbonne','Un carnet d’idées : Alfama, Graça et Belém. Dates et hébergement à choisir.'],backup:['Mes sauvegardes','Dans l’application actuelle, le téléchargement complet protège carnets, documents et souvenirs. Ce prototype ne télécharge pas de données.'],prepare:['Préparer cette journée','Trois activités proposées. Les durées et trajets restent à vérifier ; aucune faisabilité automatique n’est annoncée.'],address:['Yangshuo · 阳朔','Repère général fictif. L’adresse de départ précise reste à compléter.'],rain:['Un plan pour la pluie','Raccourcir la balade et garder une pause au café. Rien ne remplace automatiquement le programme.']};
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>details(...notes[b.dataset.detail]));
 const confirm=document.querySelector('#confirm-import');if(confirm)confirm.onclick=()=>{imported=!imported;render();document.querySelector('#confirm-import').focus();};
}
document.querySelector('#close-dialog').onclick=()=>document.querySelector('#detail').close();
render();
